use super::*;
use super::test_support::{Authorities,close_owner};
fn close_once(owner:&mut OriginalJsonReceiving<u64>,control:&mut NativeDecodeControl<'_>,payer:&mut Authorities,grant:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,RetainedCloneProgress>{close_owner(owner,control,payer,grant)}
#[test]
fn original_json_close_forwards_actual_owned_birth_and_cached_completion_work(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let stock=&row["stock"];
 let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:stock["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};
 let mut payer=Authorities::new();let one_item_loan=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};
 let mut accept=|_|true;let mut recipient=semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new_retained(&mut accept);control.install_retirement_recipient(&mut recipient).unwrap();
 let mut owner=OriginalJsonReceiving::<u64>{ledger:control.ledger_identity(),recipient:control.retirement_recipient_identity(),header:b"op",wire:ManuallyDrop::new(None),parser:ManuallyDrop::new(None),parsed:ManuallyDrop::new(None),source_admission:ManuallyDrop::new(None),typed_admission:ManuallyDrop::new(None),parsed_source:ManuallyDrop::new(None),receiver:ManuallyDrop::new(None),typed:ManuallyDrop::new(Some(row["typedValue"].as_u64().unwrap())),authority:ManuallyDrop::new(None),typed_source:ManuallyDrop::new(None),typed_alias:ManuallyDrop::new(None),canonical_alias:ManuallyDrop::new(None),typed_frame:ManuallyDrop::new(None),frame_action:ManuallyDrop::new(None),output:ManuallyDrop::new(None),canonical_projection:ManuallyDrop::new(None),canonical:ManuallyDrop::new(None),factory:ManuallyDrop::new(None),factory_close:None,error:ManuallyDrop::new(None),retirement:Default::default(),source:|value|value,offset:0,phase:Phase::Ready,closing:true,faulted:false,taking_owned:false,action:Default::default(),local_authority:ManuallyDrop::new(None)};
 assert_eq!(serde_json::to_value(owner.typed.as_ref()).unwrap(),row["typedValue"]);
 let denied=close_once(&mut owner,&mut control,&mut payer,one_item_loan);assert_eq!(denied.work,u128::from(row["deniedWork"].as_u64().unwrap()));assert_eq!(owner.typed.as_ref(),Some(&17));
 let mut saw_birth=false;
 for _ in 0..stock["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break;}let grant=RetainedCloneGrant{maximum_items:1,..bank};let turn=close_once(&mut owner,&mut control,&mut payer,grant);let progress=turn.result.unwrap().progress();assert!(progress.fits(grant));if progress.retained_capacity_bytes>0{saw_birth=true;assert_eq!(turn.work,u128::from(row["positiveWork"].as_u64().unwrap()));}bank.maximum_items-=progress.copied_items;bank.maximum_copy_bytes-=progress.copied_bytes;bank.maximum_capacity_bytes-=progress.retained_capacity_bytes;bank.maximum_release_bytes-=progress.released_bytes;}
 assert!(saw_birth);assert!(owner.terminal_is_empty());let cached=close_once(&mut owner,&mut control,&mut payer,one_item_loan);assert_eq!(cached.work,u128::from(row["cachedWork"].as_u64().unwrap()));assert_eq!(cached.result.unwrap().progress(),RetainedCloneProgress::default());drop(owner);
}
